const KEY='ses-match-workspace-v1';
function seed(){return{jobs:clone(JOB_SEED),people:clone(PERSON_SEED),sourceFiles:clone(SOURCE_SEED),importFolders:{job:{folderId:null,loadedFolderId:null,lastRead:null},person:{folderId:null,loadedFolderId:null,lastRead:null}},pending:[{id:'REV-1',type:'job',fileId:'SRC-J-10',data:{...clone(JOB_SEED[9]),price:0},source:'新規プロダクト テックリードの案件資料（サンプル）'},{id:'REV-2',type:'person',fileId:'SRC-P-6',data:{...clone(PERSON_SEED[7]),name:'松本 悠真',initials:'YM',price:0},source:'スキルシート_松本悠真_サンプル.pdf'}],saved:[],history:[{personId:'EN-001',jobId:'PJ-001',score:87,time:'本日 09:20'},{personId:'EN-002',jobId:'PJ-004',score:98,time:'本日 09:05'}],activity:[{text:'案件メールから1件を抽出しました',time:'本日 10:15',page:'review'},{text:'佐藤 健太さんのマッチングを実行',time:'本日 09:20',page:'matching'},{text:'高橋 美咲さんのマッチングを実行',time:'本日 09:05',page:'matching'},{text:'人材情報を10名登録しました',time:'昨日 17:30',page:'people'}],feedback:[]};}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();}catch{db=seed();}
let page=['dashboard','jobs','people','matching','mail','import','review'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard';
// Preserve existing registered data while upgrading the import UI.
if(!db.sourceFiles){
  db.sourceFiles=clone(SOURCE_SEED);
  for(const m of db.mails||[]){const f=db.sourceFiles.find(f=>f.id===`SRC-J-${m.id.replace('MAIL-','')}`);if(f)f.status=m.status;}
  for(const r of db.pending){if(r.mailId){r.fileId=`SRC-J-${r.mailId.replace('MAIL-','')}`;delete r.mailId;}if(r.id==='REV-2')r.fileId='SRC-P-6';}
  for(const file of db.sourceFiles){if(file.status==='確認待ち'&&!db.pending.some(r=>r.fileId===file.id))file.status=db[file.type==='job'?'jobs':'people'].some(x=>x.name===file.data.name)?'登録済':'未取込';}
  delete db.mails;
}
db.importFolders ||= {job:{folderId:null,loadedFolderId:null,lastRead:null},person:{folderId:null,loadedFolderId:null,lastRead:null}};
for(const r of db.pending){if(r.fileId){const f=db.sourceFiles.find(f=>f.id===r.fileId);if(f&&!r.source?.includes('\\'))r.source=f.name;}}
for(const a of db.activity){a.text=a.text.replace('案件メールから','案件資料から');}
let selectedPerson=db.people[0]?.id,selectedResult=null,matchRun=false,matchBusy=false;
let sourceOpVersion=0;
const sourceUI={job:{checked:[],busy:null,status:'',lastBatch:[]},person:{checked:[],busy:null,status:'',lastBatch:[]}};
