function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('保存領域が利用できないため、この画面を開いている間のみ保持します。');}}
function activity(text,pageName){db.activity.unshift({text,time:'たった今',page:pageName});db.activity=db.activity.slice(0,12);persist();}
function badge(s){let color=/募集中|提案可能|登録済|解析完了/.test(s)?'green':/確認待ち|調整中/.test(s)?'amber':/失敗/.test(s)?'red':/商談中|参画中/.test(s)?'blue':'';return`<span class="pill ${color}"><span class="dot"></span>${e(s)}</span>`;}
const tags=(skills,match)=>skills.map(s=>`<span class="tag ${match?(match.includes(s)?'match':'missing'):''}">${e(s)}</span>`).join('');
const date=v=>v?`${Number(v.slice(5,7))}月${Number(v.slice(8,10))}日〜`:'未設定';
const btn=(label,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function head(title,sub,actions='',eyebrow='WORKSPACE'){return`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
