function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('layers')}</span>SES Match<small>.</small></div><div class="brand-sub">SALES WORKSPACE</div><div class="nav-label">WORKSPACE</div>${nav('dashboard','grid')}${nav('jobs','brief',db.jobs.length)}${nav('people','users',db.people.length)}${nav('matching','spark')}<div class="nav-label">DATA IMPORT</div>${nav('mail','mail',db.sourceFiles.filter(f=>f.type==='job'&&f.status==='未取込').length)}${nav('import','upload')}${nav('review','checkfile',db.pending.length,'amber')}<div class="side-bottom"><button class="nav-item" data-action="guide">${icon('help')}使い方ガイド</button><button class="nav-item" data-action="feedback">${icon('chat')}フィードバック</button><div class="demo-side"><b><span class="dot"></span> DEMO ENVIRONMENT</b>営業向けの操作確認用モック。<br>外部AI・メールへの接続はありません。</div><div class="profile"><span class="avatar">DE</span><div>営業担当者<small>デモワークスペース</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-nav" aria-label="メニューを開く" data-action="menu">${icon('menu')}</button><span>ワークスペース</span><span>/</span><strong id="crumb">${names[page]}</strong></div><div class="header-actions"><span class="demo-badge">DEMO</span><span class="date-label tiny muted">2026年10月30日（金）</span><span class="header-line"></span><button class="icon-btn" data-action="guide" aria-label="使い方ガイド">${icon('help')}</button><button class="icon-btn" data-action="nav" data-page="review" aria-label="確認待ち情報">${icon('bell')}</button></div></header><main class="main" id="main"></main></div>`;renderView();}
function nav(p,ic,count,color=''){return`<button class="nav-item ${p===page?'active':''}" data-action="nav" data-page="${p}" ${p===page?'aria-current="page"':''}>${icon(ic)}<span>${names[p]}</span>${count?`<span class="nav-count ${color}">${count}</span>`:''}</button>`;}
function go(p){closeModal();page=p;location.hash=p;shell();window.scrollTo({top:0});}
function renderView(){document.getElementById('main').innerHTML=({dashboard:dashboard,jobs:()=>listPage('jobs'),people:()=>listPage('people'),matching:matchingPage,mail:mailPage,import:importPage,review:reviewPage}[page])()+foot();}
function dashboard(){const newJobs=db.jobs.filter(j=>j.isNew).length;return head('ダッシュボード','登録状況・確認待ち情報・実行履歴を表示します。',btn(icon('upload')+'情報を取り込む','nav','data-page="mail"')+btn(icon('spark')+'AIマッチング','nav','data-page="matching"','primary'),'OVERVIEW')+`<div class="kpis">${kpi('登録案件数',db.jobs.length,'件','brief','',`<span class="trend">+${newJobs} 新着</span><span>本日の登録案件</span>`,'jobs')}${kpi('登録人材数',db.people.length,'名','users','green','<span class="trend">'+db.people.filter(p=>p.status==='提案可能').length+'名</span><span>提案可能な人材</span>','people')}${kpi('確認待ちの取り込み',db.pending.length,'件','checkfile','orange','<span class="warn">要確認</span><span>抽出結果の確認・修正</span>','review')}${kpi('マッチング候補',candidateCount(),'件','spark','purple','<span>70点以上の案件候補（仮スコア）</span>','matching')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><h2>${icon('clock')}今日のアクション</h2><span class="sub">営業ワークフロー</span></div><div class="today-banner"><span class="rounded-icon">${icon('checkfile')}</span><div><strong>取り込み情報の確認</strong><p>抽出結果の不足項目を確認・修正して登録してください。</p></div><span class="pill amber">${db.pending.length}件 要確認</span></div>${task('抽出された情報を確認する','単価や参画条件を確認・修正して登録',db.pending.length+'件','checkfile','review','amber')}${task('保存した案件資料を取り込む','フォルダを指定して、保存済み資料から条件を整理',db.sourceFiles.filter(f=>f.type==='job'&&f.status==='未取込').length+'件','mail','mail','blue')}${task('提案可能な人材の案件を探す','条件と推薦理由を確認して候補を選定',db.people.filter(p=>p.status==='提案可能').length+'名','spark','matching','green')}</section><section class="panel"><div class="panel-head"><h2>最近登録された案件 <span class="sub">RECENT PROJECTS</span></h2><button class="text-link" data-action="nav" data-page="jobs">すべて見る ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>案件名 / 必須スキル</th><th>単価上限</th><th>ステータス</th><th></th></tr></thead><tbody>${db.jobs.slice(-1)[0]?.id?.startsWith('PJ-N')?dashboardJobs([db.jobs.at(-1),...db.jobs.slice(0,3)]):dashboardJobs(db.jobs.slice(0,4))}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>最近登録された人材</h2><button class="text-link" data-action="nav" data-page="people">すべて見る ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>人材 / 主なスキル</th><th>希望単価</th><th>稼働状況</th><th></th></tr></thead><tbody>${[...db.people].slice(-3).reverse().map(p=>`<tr><td><div class="row-title"><span class="avatar">${e(p.initials)}</span><div><strong>${e(p.name)}<small>${e(p.id)} · ${e(p.skills.slice(0,2).join(' / '))}</small></strong></div></div></td><td class="money">${p.price}<small> 万円</small></td><td>${badge(p.status)}</td><td>${btn('案件を探す '+icon('arrow'),'match-person',`data-id="${e(p.id)}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section></div><aside class="dashboard-right"><section class="panel"><div class="panel-head"><h2>最近のマッチング</h2><span class="sub">HISTORY</span></div>${db.history.slice(0,3).map(h=>{let p=db.people.find(p=>p.id===h.personId),j=db.jobs.find(j=>j.id===h.jobId);return p&&j?`<button class="recent-match" data-action="history" data-id="${e(p.id)}" data-job="${e(j.id)}"><span class="avatar">${e(p.initials)}</span><span><strong>${e(p.name)}</strong><small>${e(j.name.slice(0,13))}…</small></span><span class="score-mini">${h.score}<small>点</small></span></button>`:''}).join('')}</section><section class="panel"><div class="panel-head"><h2>最近のアクティビティ</h2>${icon('clock')}</div><div class="activity">${db.activity.slice(0,4).map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><button class="text-link" data-action="nav" data-page="${e(a.page)}" style="text-align:left;display:block"><p>${e(a.text)}</p></button><small>${e(a.time)}</small></div></div>`).join('')}</div></section><div class="system-note">${icon('shield')}<div>このワークスペースは営業確認用のモックです。<br>表示される情報・スコアはすべて架空です。</div></div></aside></div>`;}
function kpi(label,value,unit,ic,color,foot,p){return`<button class="kpi" data-action="nav" data-page="${p}"><div class="kpi-top">${label}<span class="kpi-icon ${color}">${icon(ic)}</span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-foot">${foot}</div></button>`;}
function task(title,sub,count,ic,p,color){return`<button class="task-row" data-action="nav" data-page="${p}"><span class="task-icon">${icon(ic)}</span><span class="task-content"><b>${title}</b><small>${sub}</small></span><span class="pill ${color}">${count}</span>${icon('chevron','chevron')}</button>`;}
function dashboardJobs(js){return js.map(j=>`<tr><td><button class="text-link" style="text-align:left" data-action="detail-job" data-id="${e(j.id)}"><div class="row-title"><span class="project-icon">${icon('brief')}</span><div><strong>${e(j.name)}</strong><small>${e(j.skills.join(' / '))}</small></div></div></button></td><td class="money">${j.price}<small> 万円</small></td><td>${badge(j.status)}</td><td><button class="icon-btn" aria-label="${e(j.name)}の詳細" data-action="detail-job" data-id="${e(j.id)}">${icon('chevron')}</button></td></tr>`).join('');}
function candidateCount(){return db.people.reduce((n,p)=>n+db.jobs.filter(j=>j.status!=='募集終了'&&evaluate(p,j).score>=70).length,0);}
function listPage(type){const isJob=type==='jobs',f=filters[type];let sk=[...new Set(db[type==='jobs'?'jobs':'people'].flatMap(r=>r.skills))];return head(names[type],isJob?'登録した案件を検索・確認・編集できます。':'登録した人材を検索・確認・編集できます。',btn(icon('upload')+(isJob?'案件資料取り込み':'人材資料取り込み'),'nav',`data-page="${isJob?'mail':'import'}"`)+btn(icon('plus')+'新規登録','new',`data-type="${isJob?'job':'person'}"`,'primary'),isJob?'PROJECTS':'TALENT POOL')+`<section class="panel"><div class="toolbar"><div class="filters"><div class="input-wrap">${icon('search')}<input id="list-search" data-filter="q" data-type="${type}" aria-label="キーワード検索" placeholder="${isJob?'案件名・スキル・勤務地で検索':'氏名・スキル・得意領域で検索'}" value="${e(f.q)}"></div><select aria-label="スキルで絞り込み" data-filter="skill" data-type="${type}"><option value="">すべてのスキル</option>${sk.map(s=>`<option ${s===f.skill?'selected':''}>${e(s)}</option>`).join('')}</select><select aria-label="ステータスで絞り込み" data-filter="status" data-type="${type}"><option value="">すべてのステータス</option>${(isJob?['募集中','商談中','募集終了']:['提案可能','調整中','参画中']).map(s=>`<option ${s===f.status?'selected':''}>${s}</option>`).join('')}</select></div><button class="text-link" data-action="clear-filters" data-type="${type}">${icon('refresh')}条件をクリア</button></div><div id="list-results">${listResults(type)}</div></section>`;}
function filtered(type){const f=filters[type],q=f.q.trim().toLowerCase();return db[type==='jobs'?'jobs':'people'].filter(r=>(!q||[r.name,r.id,r.place,r.domain,...r.skills].join(' ').toLowerCase().includes(q))&&(!f.skill||r.skills.includes(f.skill))&&(!f.status||r.status===f.status));}
function listResults(type){let rows=filtered(type),isJob=type==='jobs';return`<div class="summary-strip"><span>表示中 <b>${rows.length}件</b></span><span>全${isJob?db.jobs.length:db.people.length}${isJob?'案件':'名'}</span></div>${!rows.length?`<div class="empty">${icon('search')}<h3>条件に一致する${isJob?'案件':'人材'}がありません</h3><p>キーワードや絞り込み条件を変更してください。</p>${btn('条件をクリア','clear-filters',`data-type="${type}"`)}</div>`:`<div class="table-wrap"><table><thead><tr>${isJob?'<th>案件名</th><th>必須スキル</th><th>単価上限</th><th>勤務地 / 働き方</th><th>参画時期</th><th>ステータス</th>':'<th>人材ID / 氏名</th><th>主なスキル</th><th>経験年数</th><th>希望単価</th><th>稼働状況</th><th>参画可能時期</th>'}<th>操作</th></tr></thead><tbody>${rows.map(r=>isJob?`<tr><td><button class="text-link" data-action="detail-job" data-id="${e(r.id)}" style="text-align:left"><div><strong>${e(r.name)}${r.isNew?'<span class="badge-new">NEW</span>':''}</strong><small class="muted">${e(r.id)} · ${e(r.domain)}</small></div></button></td><td>${tags(r.skills)}</td><td class="money">${r.price}<small> 万円/月</small></td><td>${e(r.place)}<br><span class="tiny muted">${e(r.remote)}</span></td><td>${date(r.start)}</td><td>${badge(r.status)}</td><td>${btn('詳細','detail-job',`data-id="${e(r.id)}"`,'small')}</td></tr>`:`<tr><td><button class="text-link" data-action="detail-person" data-id="${e(r.id)}" style="text-align:left"><div class="row-title"><span class="avatar">${e(r.initials)}</span><div><strong>${e(r.name)}</strong><small>${e(r.id)} · ${e(r.domain)}</small></div></div></button></td><td>${tags(r.skills.slice(0,3))}${r.skills.length>3?`<span class="tiny muted">+${r.skills.length-3}</span>`:''}</td><td>${r.years}年</td><td class="money">${r.price}<small> 万円/月</small></td><td>${badge(r.status)}</td><td>${date(r.start)}</td><td><div class="actions">${btn('詳細','detail-person',`data-id="${e(r.id)}"`,'small')}${btn(icon('spark')+'案件を探す','match-person',`data-id="${e(r.id)}"`,'small primary')}</div></td></tr>`).join('')}</tbody></table></div><div class="list-foot"><span>${rows.length}件を表示中</span><span>架空データ / ブラウザ内保存</span></div>`}`;}
function evaluate(p,j){const missing=j.skills.filter(s=>!p.skills.includes(s)),matched=j.skills.filter(s=>p.skills.includes(s)),nice=j.nice.filter(s=>p.skills.includes(s));const budget=p.price<=j.price,timing=p.start<=j.start,work=p.remote==='常駐'||p.remote===j.remote||(p.remote==='週2日リモート'&&j.remote==='フルリモート');const expMissing=matched.filter(s=>(p.skillYears[p.skills.indexOf(s)]||0)<(j.minimum||3));let score=Math.round(5+50*(matched.length/Math.max(j.skills.length,1))+15*Number(budget)+12*Number(work)+8*Number(timing)+5*(1-expMissing.length/Math.max(j.skills.length,1))+5*(nice.length/Math.max(j.nice.length,1)));score=Math.max(20,Math.min(98,score));if(p.id==='EN-001'&&j.id==='PJ-001'&&missing.length===0&&budget&&timing&&work&&p.price===75&&j.price===80)score=87;
let concerns=[];if(missing.length)concerns.push(`必須スキル ${missing.join('・')} の経験が未登録です。`);if(expMissing.length)concerns.push(`${expMissing.join('・')}の経験が目安の${j.minimum||3}年に届きません。`);if(!budget)concerns.push(`希望単価が案件上限を${p.price-j.price}万円超過しています。`);if(!work)concerns.push(`人材の希望は${p.remote}、案件は${j.remote}です。勤務条件の調整が必要です。`);if(!timing)concerns.push(`人材の参画可能日は${date(p.start)}。案件開始${date(j.start)}に間に合いません。`);if(p.place==='横浜'&&j.place!=='横浜'&&j.remote!=='フルリモート')concerns.push('横浜希望に対して勤務地が異なるため、通勤可否を確認してください。');if(j.memo)concerns.push(j.memo);let reason=matched.length?`${matched.join('・')}の経験が${missing.length?'一部の':'必須'}スキルと一致。${budget?'希望単価も案件の条件内です。':'単価条件の調整が必要です。'}`:'必須スキルとの一致が少ないため、現在の条件では優先度が低い候補です。';return{j,score,missing,matched,nice,budget,timing,work,expMissing,concerns,reason};}
function currentPerson(){return db.people.find(p=>p.id===selectedPerson)||db.people[0];}
function results(){let p=currentPerson();return db.jobs.filter(j=>j.status!=='募集終了').map(j=>evaluate(p,j)).sort((a,b)=>b.score-a.score);}
function matchingPage(){const p=currentPerson();return head('AIマッチング','人材と案件の条件を比較し、候補と適合理由を表示します。',btn(icon('users')+'人材一覧へ','nav','data-page="people"'),'AI MATCHING')+`<section class="panel"><div class="selection-card"><div><label for="person-select">01　マッチングする人材を選択</label><select id="person-select" ${matchBusy?'disabled':''}>${db.people.map(r=>`<option value="${e(r.id)}" ${r.id===p.id?'selected':''}>${e(r.name)}　/　${e(r.id)}</option>`).join('')}</select></div><div><div class="person-inline"><span class="avatar">${e(p.initials)}</span><div><h3>${e(p.name)} <span class="pill ${p.status==='提案可能'?'green':'blue'}">${e(p.status)}</span></h3><small>${e(p.domain)} / 実務経験 ${p.years}年</small></div></div><div style="margin-top:9px">${p.skills.map((s,i)=>`<span class="tag">${e(s)} ${p.skillYears[i]||0}年</span>`).join('')}</div><div class="mini-info"><span>希望 <b>${p.price}万円</b></span><span>${e(p.remote)}</span><span>${date(p.start)}</span></div></div>${btn(icon('spark')+(matchBusy?'条件を照合中…':matchRun?'もう一度実行':'AIマッチング実行'),'run-match',matchBusy?'disabled':'','primary')}</div></section><p class="matching-note">${icon('shield')}デモの仮スコアです。AIには接続せず、登録条件に基づく簡易ルールで候補を表示します。</p>${matchBusy?loading('人材と案件の条件を照合しています','スキル・単価・働き方・参画時期を確認中…'):matchRun?matchResults():`<section class="match-hero-empty"><div class="upload-icon">${icon('spark')}</div><h2>マッチング未実行</h2><p>人材を選択して「AIマッチング実行」をクリックしてください。<br>おすすめ案件と、提案前に確認したいポイントを表示します。</p><div class="match-checks"><span>${icon('check')}スキルの一致</span><span>${icon('check')}単価・働き方</span><span>${icon('check')}推薦理由と懸念点</span></div></section>`}`;}
function matchResults(){let rr=results(),f=filters.matching.min;if(f==='high')rr=rr.filter(r=>r.score>=70);if(f==='saved')rr=rr.filter(r=>db.saved.includes(r.j.id));let sel=rr.find(r=>r.j.id===selectedResult)||rr[0];if(sel)selectedResult=sel.j.id;return`<div class="result-head"><div><h2>おすすめ案件 <span class="pill blue">${rr.length}件</span></h2><p>${e(currentPerson().name)}さんの条件に対して、スコアの高い順に表示</p></div><select id="result-filter" aria-label="結果の絞り込み"><option value="all" ${f==='all'?'selected':''}>すべての候補</option><option value="high" ${f==='high'?'selected':''}>70点以上</option><option value="saved" ${f==='saved'?'selected':''}>保存した候補</option></select></div>${!rr.length?`<div class="panel empty">${icon('bookmark')}<h3>該当する候補がありません</h3><p>「すべての候補」に切り替えて候補を確認してください。</p></div>`:`<div class="result-grid"><div>${rr.map((r,i)=>matchCard(r,i,sel.j.id)).join('')}</div>${fitPanel(sel)}</div>`}`;}
function matchCard(r,i,id){const j=r.j;return`<article class="match-card ${id===j.id?'selected':''}"><div class="match-card-head"><button style="background:none;text-align:left;color:inherit;padding:0;flex:1" data-action="select-result" data-id="${e(j.id)}" aria-label="${e(j.name)}の適合理由を表示"><div class="rank">${String(i+1).padStart(2,'0')} ${i===0?'TOP MATCH':''}${r.score>=85?'<span class="pill green">高い適合度</span>':''}</div><h3>${e(j.name)}</h3><span class="company">${e(j.id)} · ${e(j.company)}</span></button><div class="score-ring" style="--score:${r.score}"><span>${r.score}<small>仮スコア</small></span></div><button class="save-btn ${db.saved.includes(j.id)?'saved':''}" data-action="save-candidate" data-id="${e(j.id)}" aria-label="${db.saved.includes(j.id)?'候補の保存を解除':'候補を保存'}" aria-pressed="${db.saved.includes(j.id)}">${icon('bookmark')}</button></div><div class="match-meta"><span class="money">〜${j.price}万円/月</span><span>${icon('pin')}${e(j.place)}</span><span>${icon('monitor')}${e(j.remote)}</span><span>${icon('clock')}${date(j.start)}</span></div><div>${tags(j.skills,currentPerson().skills)}</div><div class="reason-line">${icon('spark')}<span>${e(r.reason)}</span></div><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div class="warning-line">${icon('warning')}確認ポイント ${r.concerns.length}件</div><button class="btn text small" data-action="select-result" data-id="${e(j.id)}">推薦理由・懸念点 ${icon('arrow')}</button></div></article>`;}
function fitPanel(r){let p=currentPerson(),j=r.j;return`<section class="panel fit-panel"><div class="panel-head"><h2>${icon('checkfile')}適合理由・確認ポイント</h2><span class="pill">${r.score}点</span></div><div class="panel-body"><h3 class="fit-title">${e(j.name)}</h3><p class="fit-sub">${e(j.id)}　/　${e(p.name)}さんとの比較</p><div class="fit-row"><span class="label">必須スキル</span><span class="fit-value"><b class="${r.missing.length?'bad':'good'}">${r.matched.length} / ${j.skills.length} 一致</b><br>${tags(j.skills,p.skills)}</span></div><div class="fit-row"><span class="label">尚可スキル</span><span class="fit-value">${r.nice.length} / ${j.nice.length} 一致<br>${tags(j.nice,p.skills)}</span></div><div class="fit-row"><span class="label">技術経験</span><span class="fit-value ${r.expMissing.length?'warn':'good'}">${r.expMissing.length?'経験年数に確認あり':'登録経験は目安を充足'}<br><span class="tiny muted">必須技術 各${j.minimum||3}年以上（仮設定）</span></span></div><div class="fit-row"><span class="label">単価条件</span><span class="fit-value ${r.budget?'good':'bad'}">${r.budget?'条件内':'上限超過'}<br><span class="tiny muted">希望 ${p.price}万円 / 上限 ${j.price}万円</span></span></div><div class="fit-row"><span class="label">勤務条件</span><span class="fit-value ${r.work?'good':'bad'}">${r.work?'リモート条件が一致':'条件の調整が必要'}<br><span class="tiny muted">希望 ${e(p.remote)}<br>案件 ${e(j.place)} / ${e(j.remote)}</span></span></div><div class="fit-row"><span class="label">参画時期</span><span class="fit-value ${r.timing?'good':'bad'}">${r.timing?'開始日に参画可能':'開始時期に差異あり'}<br><span class="tiny muted">人材 ${date(p.start)}<br>案件 ${date(j.start)}</span></span></div><div class="fit-section"><h4 class="good">${icon('spark')}推薦理由</h4><p>${e(r.reason)} ${r.nice.length?`${e(r.nice.join('・'))}の経験も活かせる候補です。`:''}</p><div class="bar"><span style="width:${r.score}%"></span></div></div><div class="fit-section warning"><h4>${icon('warning')}提案前に確認したいこと</h4>${r.concerns.map(c=>`<p style="margin-bottom:6px">・${e(c)}</p>`).join('')}</div><div class="fit-section">${btn('案件の詳細を確認 '+icon('arrow'),'detail-job',`data-id="${e(j.id)}"`,'small')}</div><p class="tiny muted" style="margin-top:16px">※ 仮の評価であり、成約や適合性を保証するものではありません。</p></div></section>`;}
function loading(title,sub){return`<div class="loading-area" role="status"><div class="spinner"></div><h3>${title}</h3><p>${sub}</p><div class="loading-dots"><i></i><i></i><i></i></div><span class="pill blue">デモの解析を実行中</span></div>`;}
async function runMatch(){if(matchBusy)return;const version=++matchVersion;matchBusy=true;matchRun=false;selectedResult=null;renderView();await new Promise(r=>setTimeout(r,1300));if(version!==matchVersion)return;matchBusy=false;matchRun=true;filters.matching.min='all';let p=currentPerson(),top=results()[0];if(top){selectedResult=top.j.id;db.history.unshift({personId:p.id,jobId:top.j.id,score:top.score,time:'たった今'});db.history=db.history.slice(0,10);activity(`${p.name}さんのマッチングを実行`,'matching');}if(page==='matching')renderView();toast('マッチングが完了しました。推薦理由と懸念点をご確認ください。');}
function mailPage(){return folderImportPage('job');}
function importPage(){return folderImportPage('person');}
function reviewPage(){let rs=db.pending.filter(r=>reviewTab==='all'||r.type===reviewTab);return head('取り込み結果確認','抽出された情報を確認・修正してから、一覧に登録します。',btn(icon('upload')+'情報を取り込む','nav','data-page="mail"'),'REVIEW QUEUE')+`<section class="panel"><div class="tab-row">${[['all','すべて'],['job','案件'],['person','人材']].map(r=>`<button class="tab ${reviewTab===r[0]?'active':''}" data-action="review-tab" data-id="${r[0]}">${r[1]} <span class="pill">${db.pending.filter(x=>r[0]==='all'||x.type===r[0]).length}</span></button>`).join('')}</div>${rs.length?rs.map(r=>`<div class="review-row"><span class="task-icon">${icon(r.type==='job'?'brief':'users')}</span><div><h3>${e(r.data.name)}</h3><p>${e(r.source)}</p><div style="margin-top:6px"><span class="pill ${r.type==='job'?'blue':'purple'}">${r.type==='job'?'案件':'人材'}</span> <span class="pill amber">${r.data.price?'内容確認待ち':'単価の確認が必要'}</span></div></div><div class="actions">${btn(icon('edit')+'確認・編集','review-edit',`data-id="${e(r.id)}"`,'small primary')}</div></div>`).join(''):`<div class="empty">${icon('checkfile')}<h3>確認待ちの情報はありません</h3><p>フォルダに保存した案件資料やスキルシートを取り込めます。</p>${btn('案件資料を取り込む','nav','data-page="mail"')}</div>`}</section>`;}
function openDrawer(title,sub,content,footer){document.getElementById('overlay').innerHTML=`<div class="overlay-bg" data-backdrop="true"><section class="drawer" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="drawer-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close" aria-label="閉じる">${icon('close')}</button></div><div class="drawer-content">${content}</div><div class="drawer-footer">${footer}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.drawer button,.drawer input')?.focus(),20);}
function openModal(title,sub,content){document.getElementById('overlay').innerHTML=`<div class="overlay-bg modal-bg" data-backdrop="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="drawer-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close" aria-label="閉じる">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal button')?.focus(),20);}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';modalState=null;}
function fieldDisplay(label,value,full=false){return`<div class="detail-field ${full?'full':''}"><label>${label}</label><div>${value}</div></div>`;}
function detail(type,id){const r=db[type==='job'?'jobs':'people'].find(x=>x.id===id);if(!r)return;modalState={type,id};let job=type==='job';openDrawer(job?'案件詳細':'人材プロフィール',`${e(r.id)} / 架空データ`,job?`<div class="detail-hero">${badge(r.status)}<h3>${e(r.name)}</h3><p>${e(r.summary)}</p></div><div class="detail-grid">${fieldDisplay('必須スキル',tags(r.skills),true)}${fieldDisplay('尚可スキル',tags(r.nice),true)}${fieldDisplay('単価上限',`${r.price} 万円 / 月`)}${fieldDisplay('参画開始時期',date(r.start))}${fieldDisplay('勤務地',e(r.place))}${fieldDisplay('リモート可否',e(r.remote))}${fieldDisplay('契約期間',e(r.period))}${fieldDisplay('必須技術の経験目安',`各${r.minimum||3}年以上`)}${fieldDisplay('提供元',e(r.company),true)}${fieldDisplay('備考・確認事項',e(r.memo)||'なし',true)}</div>`:`<div class="detail-hero"><div class="person-inline"><span class="avatar">${e(r.initials)}</span><div><h3>${e(r.name)}</h3>${badge(r.status)}</div></div><p>${e(r.memo)}</p></div><div class="detail-grid">${fieldDisplay('保有スキル・技術経験',r.skills.map((s,i)=>`<span class="tag">${e(s)} ${r.skillYears[i]||0}年</span>`).join(''),true)}${fieldDisplay('実務経験',`${r.years}年`)}${fieldDisplay('得意領域',e(r.domain))}${fieldDisplay('希望単価',`${r.price} 万円 / 月`)}${fieldDisplay('参画可能時期',date(r.start))}${fieldDisplay('希望勤務地',e(r.place))}${fieldDisplay('リモート希望',e(r.remote))}</div>`,btn('閉じる','close')+btn(icon('edit')+'編集する','edit-existing',`data-type="${type}" data-id="${e(id)}"`)+(job?'':btn(icon('spark')+'この人材で案件を探す','match-person',`data-id="${e(id)}"`,'primary')));}
function inputField(name,label,value,kind='text',required=false,full=false,options=null,attention=false,help=''){return`<div class="field ${full?'full':''} ${attention?'attention':''}"><label for="f-${name}">${label}${required?'<em>必須</em>':''}</label>${options?`<select id="f-${name}" name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${e(o)}" ${o===value?'selected':''}>${e(o)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="f-${name}" name="${name}" ${required?'required':''}>${e(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${kind}" value="${e(value)}" ${required?'required':''} ${kind==='number'?'min="0.1" max="999" step="0.1"':''}>`}${help?`<small>${help}</small>`:''}</div>`;}
function openEditor(type,r={},opts={}){const job=type==='job';modalState={type,original:clone(r),...opts};let title=opts.pendingId?'抽出結果の確認・編集':opts.existingId?'登録情報の編集':job?'案件を新規登録':'人材を新規登録';const origin=opts.pendingId?db.pending.find(x=>x.id===opts.pendingId):null;const form=`${origin?`<div class="source-origin">${icon('folder')}<span><b>取り込み元の資料</b>${e(origin.source)}</span></div>`:''}${opts.pendingId?`<div class="edit-alert">${icon('warning')}<div><b>抽出内容を確認してから登録してください</b>${!r.price?'希望単価・単価上限が未確定です。黄色の項目を入力してください。':'単価・経験年数・参画条件に誤りがないか確認してください。'}</div></div>`:''}<form id="edit-form"><div class="form-grid">${inputField('name',job?'案件名':'氏名（架空）',r.name||'','text',true,true)}${job?inputField('summary','業務概要',r.summary||'','textarea',true,true):inputField('domain','得意領域',r.domain||'','text',true,true)}${inputField('skills',job?'必須スキル（カンマ区切り）':'保有スキル（カンマ区切り）',(r.skills||[]).join(', '),'text',true,true)}${job?inputField('nice','尚可スキル（カンマ区切り）',(r.nice||[]).join(', '),'text',false,true):inputField('skillYears','技術別の経験年数（スキルと同じ順・カンマ区切り）',(r.skillYears||[]).join(', '),'text',true,true,null,false,'例：Python, Django, AWS → 5, 3, 2')}${inputField('price',job?'単価上限（万円 / 月）':'希望単価（万円 / 月）',r.price||'','number',true,false,null,!r.price,'デモ用の仮の単価を入力してください。')}${job?inputField('minimum','必須技術の経験目安（年）',r.minimum||3,'number',true):inputField('years','実務経験年数',r.years||'','number',true)}${inputField('place',job?'勤務地':'希望勤務地',r.place||'','text',true)}${inputField('remote',job?'リモート可否':'リモート希望',r.remote||'週2日リモート','text',true,false,['フルリモート','週2日リモート','常駐'])}${inputField('start',job?'参画開始時期':'参画可能時期',r.start||'2026-12-01','date',true)}${inputField('status','ステータス',r.status||(job?'募集中':'提案可能'),'text',true,false,job?['募集中','商談中','募集終了']:['提案可能','調整中','参画中'])}${job?inputField('period','契約期間',r.period||'3ヶ月〜（更新あり）','text',true,true):''}${inputField('memo','備考・確認事項',r.memo||'','textarea',false,true)}</div><p id="form-error" class="warning-inline" role="alert"></p></form>`;openDrawer(title,opts.pendingId?'AI抽出のシミュレーション / 未確定データ':'ブラウザ内に保存 / 架空の情報のみ入力してください',form,btn('キャンセル','close')+`<button class="btn primary" type="submit" form="edit-form">${icon('check')}${opts.existingId?'変更を保存':'確認して登録'}</button>`);}
function saveForm(form){if(!modalState)return;const s=modalState,f=Object.fromEntries(new FormData(form)),split=x=>(x||'').split(/[,、，]/).map(x=>x.trim()).filter(Boolean);const skills=[...new Set(split(f.skills))];let sy=split(f.skillYears).map(Number);if(!f.name.trim()||!skills.length){document.getElementById('form-error').textContent='氏名・案件名と、1つ以上のスキルを入力してください。';return;}if(s.type==='person'&&(sy.length!==skills.length||sy.some(n=>!Number.isFinite(n)||n<0||n>60))){document.getElementById('form-error').textContent='技術別の経験年数は、保有スキルと同じ件数で0〜60の数値を入力してください。';return;}let r={...s.original,...f,skills,price:Number(f.price)};if(s.type==='job'){r.nice=split(f.nice);r.minimum=Number(f.minimum);r.company=r.company||'手動登録（架空）';r.domain=r.domain||'新規案件';r.isNew=!s.existingId;}else{r.skillYears=sy;r.years=Number(f.years);r.initials=r.initials||'DE';}let target=s.type==='job'?'jobs':'people';if(s.existingId){r.id=s.existingId;db[target]=db[target].map(x=>x.id===r.id?r:x);}else{r.id=`${s.type==='job'?'PJ':'EN'}-N${Date.now().toString().slice(-7)}`;db[target].push(r);}if(s.pendingId){let rev=db.pending.find(x=>x.id===s.pendingId);if(rev?.fileId){const file=db.sourceFiles.find(f=>f.id===rev.fileId);if(file)file.status='登録済';}db.pending=db.pending.filter(x=>x.id!==s.pendingId);}let edited=!!s.existingId;activity(`${s.type==='job'?'案件':'人材'}「${r.name}」を${edited?'更新':'登録'}しました`,target);filters[target]={q:'',skill:'',status:''};go(target);toast(`${r.name}を${edited?'更新':'登録'}しました。`);}
function guide(){openModal('SES Match の使い方','営業担当者向け / 操作できるプロトタイプ',`<div class="panel-body">${[['A','案件資料を取り込む','営業が案件資料をPCに保存 → サンプルフォルダを指定・読み込み → ファイル選択・解析 → 確認・編集 → 案件登録','mail','案件資料取り込みへ'],['B','人材資料を取り込む','営業が人材資料をPCに保存 → サンプルフォルダを指定・読み込み → ファイル選択・解析 → 希望条件を確認 → 人材登録','import','人材取り込みへ'],['C','人材に合う案件を探す','人材を選択 → AIマッチング実行 → 仮スコア順で比較 → 推薦理由・懸念点を確認','matching','マッチングを試す']].map(r=>`<div class="guide-block"><h3><span class="pill blue">FLOW ${r[0]}</span>　${r[1]}</h3><p>${r[2]}</p>${btn(r[4]+' '+icon('arrow'),'nav',`data-page="${r[3]}"`,'small primary')}</div>`).join('')}<div class="note-box">メールや資料を保存するのは営業担当者です。指定するのはPC上の保存フォルダを想定しています。<br>このモックはサンプルフォルダと架空資料のみで動作し、実際のPCやメールには接続しません。<br><br>変更はこの端末のブラウザ内に保存されます。ほかの営業担当者の操作には影響しません。実データは入力せず、架空の条件でお試しください。</div><div class="actions" style="justify-content:flex-end;margin-top:16px">${btn(icon('refresh')+'初期データに戻す','confirm-reset','','small')}</div></div>`);}
function feedback(){openModal('操作して気づいたこと','このブラウザ内にメモとして保存できます。',`<form id="feedback-form" class="feedback-form"><p class="feedback-intro">必要な検索条件やマッチングの判断基準など、気づいた点を残してください。メモは端末内に保存され、自動送信されません。</p><div class="field"><label for="feedback-section">対象の画面</label><select id="feedback-section" name="section">${Object.entries(names).map(([k,v])=>`<option ${k===page?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="feedback-body">気づいた点・改善したいこと</label><textarea id="feedback-body" name="body" required maxlength="3000" placeholder="例：案件検索で単価の範囲も指定したい"></textarea></div><div class="actions" style="justify-content:flex-end;margin-top:20px">${btn('メモをコピー','copy-feedback',db.feedback.length?'':'disabled') }<button type="submit" class="btn primary">メモを保存</button></div>${db.feedback.length?`<div class="note-box"><b>保存済み ${db.feedback.length}件</b>${db.feedback.slice(-3).reverse().map(f=>`<p><b>${e(f.section)}</b><br>${e(f.body)}</p>`).join('')}</div>`:''}</form>`);}
let toastTimeout;function toast(text){const t=document.getElementById('toast');t.innerHTML=icon('check')+`<span>${e(text)}</span>`;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),3600);}
document.addEventListener('click',async event=>{let el=event.target.closest('[data-action]');if(!el){if(event.target.dataset.backdrop==='true')closeModal();return;}let a=el.dataset.action,id=el.dataset.id,type=el.dataset.type;if(a.startsWith('source-'))return handleSourceAction(a,type,id);if(a==='nav')return go(el.dataset.page);if(a==='close')return closeModal();if(a==='menu')return document.querySelector('.sidebar').classList.toggle('open');if(a==='guide')return guide();if(a==='feedback')return feedback();if(a==='detail-job')return detail('job',id);if(a==='detail-person')return detail('person',id);if(a==='match-person'){matchVersion++;selectedPerson=id;matchRun=false;matchBusy=false;go('matching');return;}if(a==='history'){selectedPerson=id;selectedResult=el.dataset.job;matchRun=true;return go('matching');}if(a==='run-match')return runMatch();if(a==='select-result'){selectedResult=id;renderView();if(innerWidth<1000)document.querySelector('.fit-panel')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(a==='save-candidate'){db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id];persist();renderView();return toast(db.saved.includes(id)?'候補を保存しました。結果の絞り込みから確認できます。':'候補の保存を解除しました。');}if(a==='clear-filters'){filters[type]={q:'',skill:'',status:''};return renderView();}if(a==='new')return openEditor(type);if(a==='edit-existing'){let r=db[type==='job'?'jobs':'people'].find(x=>x.id===id);return openEditor(type,r,{existingId:id});}if(a==='review-tab'){reviewTab=id;return renderView();}if(a==='review-edit'){let rev=db.pending.find(r=>r.id===id);if(rev)return openEditor(rev.type,rev.data,{pendingId:rev.id});}if(a==='confirm-reset')return openModal('初期データに戻しますか？','追加・編集データ、候補の保存、フィードバックメモが消去されます。',`<div class="panel-body"><p class="feedback-intro">このブラウザのデモデータのみを初期状態に戻します。</p><div class="actions" style="justify-content:flex-end">${btn('キャンセル','close')}${btn('初期データに戻す','reset','','primary')}</div></div>`);if(a==='reset'){matchVersion++;matchBusy=false;db=seed();persist();selectedPerson=db.people[0].id;sourceOpVersion++;for(const t of ['job','person'])sourceUI[t]={checked:[],busy:null,status:'',lastBatch:[]};matchRun=false;filters={jobs:{q:'',skill:'',status:''},people:{q:'',skill:'',status:''},matching:{min:'all'}};go('dashboard');return toast('初期データに戻しました。');}if(a==='copy-feedback'){const text=db.feedback.map(f=>`【${f.section}】\n${f.body}`).join('\n\n');try{await navigator.clipboard.writeText(text);toast('フィードバックメモをコピーしました。');}catch{openModal('保存したフィードバック','テキストを選択してコピーできます。',`<div class="panel-body"><textarea style="width:100%;height:250px" readonly>${e(text)}</textarea></div>`);}return;}});
document.addEventListener('input',event=>{let el=event.target;if(el.dataset.filter==='q'){filters[el.dataset.type].q=el.value;document.getElementById('list-results').innerHTML=listResults(el.dataset.type);}});
document.addEventListener('change',event=>{let el=event.target;if(el.dataset.sourceCheck){const t=el.dataset.type,ui=sourceUI[t];ui.checked=el.checked?[...new Set([...ui.checked,el.dataset.sourceCheck])]:ui.checked.filter(id=>id!==el.dataset.sourceCheck);return renderView();}if(el.dataset.sourceAll){const t=el.dataset.type;sourceUI[t].checked=el.checked?visibleSourceFiles(t).filter(canParse).map(f=>f.id):[];return renderView();}if(el.dataset.sourceStatus){const t=el.dataset.type;sourceUI[t].status=el.value;sourceUI[t].checked=[];return renderView();}if(el.dataset.filter&&el.dataset.filter!=='q'){filters[el.dataset.type][el.dataset.filter]=el.value;document.getElementById('list-results').innerHTML=listResults(el.dataset.type);}if(el.id==='person-select'){matchVersion++;selectedPerson=el.value;matchRun=false;selectedResult=null;renderView();}if(el.id==='result-filter'){filters.matching.min=el.value;renderView();}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='edit-form')saveForm(event.target);if(event.target.id==='feedback-form'){let f=Object.fromEntries(new FormData(event.target));if(!f.body.trim())return;db.feedback.push({...f,body:f.body.trim()});persist();feedback();toast('フィードバックをこのブラウザに保存しました。');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();document.querySelector('.sidebar')?.classList.remove('open');}if(event.key==='Tab'&&document.querySelector('[role="dialog"]')){let nodes=[...document.querySelector('[role="dialog"]').querySelectorAll('button:not(:disabled),input,select,textarea')];let first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(names[next]&&next!==page){page=next;closeModal();shell();window.scrollTo({top:0});}});
shell();
